function icon(name, size, cls) {
  var body = SOLAR[name];
  if (!body) return "";
  size = size || 18;
  return '<svg class="si' + (cls ? ' ' + cls : '') + '" width="' + size + '" height="' + size + '" viewBox="0 0 24 24" aria-hidden="true">' + body + '</svg>';
}

